import csv
import os
from collections import defaultdict

# Українська абетка для сортування: є, і, ї, ґ стоять на своїх місцях, а не за кодами Unicode
АБЕТКА = "абвгґдеєжзиіїйклмнопрстуфхцчшщьюя"


def ключ_абетки(текст):
    return [
        АБЕТКА.index(c) if c in АБЕТКА else len(АБЕТКА) + ord(c)
        for c in текст.lower()
    ]


def час_у_хвилини(значення):
    години, хвилини = значення.strip().split(":")
    return int(години) * 60 + int(хвилини)


def з_хвилин_у_рядок(хвилини):
    return f"{хвилини // 60}:{хвилини % 60:02d}"


def main():
    шлях = os.path.join("дані", "зміни.csv")

    записи = []  # (працівник, дата, початок_текст, кінець_текст, початок_хв, кінець_хв), у порядку файлу
    with open(шлях, newline="", encoding="utf-8-sig") as f:
        for рядок in csv.DictReader(f):
            працівник = рядок["працівник"].strip()
            дата = рядок["дата"].strip()
            початок = рядок["початок"].strip()
            кінець = рядок["кінець"].strip()
            записи.append((
                працівник,
                дата,
                початок,
                кінець,
                час_у_хвилини(початок),
                час_у_хвилини(кінець),
            ))

    # Табель: сумарна тривалість змін кожного працівника
    сума = defaultdict(int)
    for працівник, _, _, _, початок_хв, кінець_хв in записи:
        сума[працівник] += кінець_хв - початок_хв

    for працівник in sorted(сума, key=ключ_абетки):
        загалом = сума[працівник]
        print(f"{працівник}: {загалом // 60} год {загалом % 60:02d} хв")

    # Перетини: групуємо зміни за працівником і датою, зберігаючи порядок файлу
    групи = defaultdict(list)
    for запис in записи:
        групи[(запис[0], запис[1])].append(запис)

    перетини = []
    for (працівник, дата) in sorted(групи, key=lambda k: (ключ_абетки(k[0]), k[1])):
        зміни_дня = групи[(працівник, дата)]
        for i in range(len(зміни_дня)):
            for j in range(i + 1, len(зміни_дня)):
                _, _, п1, к1, s1, e1 = зміни_дня[i]
                _, _, п2, к2, s2, e2 = зміни_дня[j]
                # Впритул (кінець однієї = початок іншої) перетином не вважається
                if max(s1, s2) < min(e1, e2):
                    перетини.append(
                        f"Перетин: {працівник} {дата} {п1}–{к1} і {п2}–{к2}"
                    )

    if перетини:
        for рядок in перетини:
            print(рядок)
    else:
        print("Перетинів немає")


if __name__ == "__main__":
    main()

